def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    strong_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) >= 6 and opp.get('budget', 0) >= DAILY_SALARY:
                    strong_prev.append(float(bid))

    if not alive_opps:
        if hp <= 3 or no_water >= 1:
            return float(min(budget, 45.0))
        return float(min(budget, 18.0))

    tight_supply = supply <= 17.0
    loose_supply = supply >= 22.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strong_high = max(strong_prev) if strong_prev else highest_prev

    urgency = 0
    if hp <= 3:
        urgency += 3
    elif hp <= 5:
        urgency += 2
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    elif loose_supply:
        urgency -= 1
    if day >= 8:
        urgency += 1

    if urgency >= 5:
        target = max(78.0, strong_high + 3.0)
    elif urgency >= 3:
        target = max(58.0, strong_high + 1.5)
    else:
        if highest_prev >= 95.0:
            target = 26.0 if hp > 5 and no_water == 0 else 72.0
        elif highest_prev >= 75.0:
            target = 42.0 if not tight_supply else 61.0
        elif highest_prev > 0.0:
            target = max(34.0, highest_prev + 1.0)
        else:
            target = 32.0 if tight_supply else 24.0

    affordable_soft = budget
    if hp > 5 and no_water == 0 and day <= 6:
        affordable_soft = min(affordable_soft, budget * 0.72)

    bid = min(target, affordable_soft)

    if budget < 25:
        bid = budget
    elif hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, 88.0))

    if loose_supply and hp >= 7 and no_water == 0 and highest_prev >= 85.0:
        bid = min(bid, 28.0)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], 75.0)

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
    max_prev_bid = max(yesterday_bids)

    if my_status['hp'] < 4:
        return min(my_status['budget'], max_prev_bid + 10.0)

    if supply < WATER_REQ + 2:
        return min(my_status['budget'], max_prev_bid + 5.0)

    return min(my_status['budget'], max(avg_prev_bid * 0.9, 60.0))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 1:
        bid = DAILY_SALARY * 0.98
    elif my_status['hp'] <= 3:
        bid = DAILY_SALARY * 0.88
    elif my_status['hp'] <= 5:
        bid = DAILY_SALARY * 0.75

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 5:
                bid = max(bid, highest_prev_bid + 2)
            else:
                bid = max(bid, highest_prev_bid + 5, DAILY_SALARY * 0.9)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            bid = max(bid, highest_prev_bid + 3)
        else:
            bid = max(bid, highest_prev_bid * 1.1)

    current_supply = day_context['supply']
    if current_supply <= 17.0 and num_alive_opponents >= 3:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif current_supply <= 19.0 and num_alive_opponents >= 2:
        bid = max(bid, DAILY_SALARY * 0.85)
    elif current_supply >= 23.0 and num_alive_opponents <= 2:
        if my_status['hp'] > 5:
            bid = min(bid, DAILY_SALARY * 0.5)

    current_day = day_context['day']
    if current_day >= EPISODE_DAYS - 2:
        if my_status['hp'] <= 4:
            bid = max(bid, DAILY_SALARY * 0.98)
        else:
            bid = max(bid, DAILY_SALARY * 0.75)

    final_bid = min(my_status['budget'], bid)
    return max(0.0, final_bid)
